const AGENT_NATIVE_ROUTE_WARMUP_STRATEGIES = new Set([
    "off",
    "marked",
    "intent",
    "render",
    "viewport",
]);
export const DEFAULT_AGENT_NATIVE_ROUTE_WARMUP_SELECTOR = 'a[data-an-prefetch="render"][href]';
export const DEFAULT_AGENT_NATIVE_ROUTE_WARMUP_CONFIG = {
    strategy: "viewport",
    data: true,
    modules: true,
    selector: DEFAULT_AGENT_NATIVE_ROUTE_WARMUP_SELECTOR,
    maxConcurrent: 8,
};
export function isAgentNativeRouteWarmupStrategy(value) {
    return (typeof value === "string" &&
        AGENT_NATIVE_ROUTE_WARMUP_STRATEGIES.has(value));
}
function normalizeRouteWarmupStrategy(value, fallback = DEFAULT_AGENT_NATIVE_ROUTE_WARMUP_CONFIG.strategy) {
    return isAgentNativeRouteWarmupStrategy(value) ? value : fallback;
}
function applyRouteWarmupConfigInput(base, input = true) {
    if (input === false) {
        return { ...base, strategy: "off" };
    }
    if (typeof input === "string") {
        return {
            ...base,
            strategy: normalizeRouteWarmupStrategy(input, base.strategy),
        };
    }
    if (input === true || input === undefined) {
        return { ...base };
    }
    return {
        ...base,
        ...input,
        strategy: normalizeRouteWarmupStrategy(input.strategy, base.strategy),
        data: typeof input.data === "boolean" ? input.data : base.data,
        modules: typeof input.modules === "boolean" ? input.modules : base.modules,
        selector: typeof input.selector === "string" && input.selector.trim()
            ? input.selector
            : base.selector,
        maxConcurrent: typeof input.maxConcurrent === "number" &&
            Number.isFinite(input.maxConcurrent) &&
            input.maxConcurrent > 0
            ? Math.floor(input.maxConcurrent)
            : base.maxConcurrent,
    };
}
export function normalizeAgentNativeRouteWarmupConfig(input = true) {
    return applyRouteWarmupConfigInput(DEFAULT_AGENT_NATIVE_ROUTE_WARMUP_CONFIG, input);
}
export function mergeAgentNativeRouteWarmupConfig(baseInput, overrideInput) {
    return applyRouteWarmupConfigInput(normalizeAgentNativeRouteWarmupConfig(baseInput), overrideInput);
}
